{'code': 'async def _maybe_release_last_part(self) -> None:
        """Ensures that the last read body part is read completely."""
        if self._last_part is not None:
            if not self._last_part.at_eof():
                await self._last_part.release()
            self._unread.extend(self._last_part._unread)
            self._last_part = None', 'language': 'python', 'source': 'codesearchnet'}

{'code': 'async def write(self, writer: Any,
                    close_boundary: bool=True) -> None:
        """Write body."""
        if not self._parts:
            return

        for part, encoding, te_encoding in self._parts:
            await writer.write(b'--' + self._boundary + b'\r\n')
            await writer.write(part._binary_headers)

            if encoding or te_encoding:
                w = MultipartPayloadWriter(writer)
                if encoding:
                    w.enable_compression(encoding)
                if te_encoding:
                    w.enable_encoding(te_encoding)
                await part.write(w)  # type: ignore
                await w.write_eof()
            else:
                await part.write(writer)

            await writer.write(b'\r\n')

        if close_boundary:
            await writer.write(b'--' + self._boundary + b'--\r\n')', 'language': 'python', 'source': 'codesearchnet'}

